 using System.Text.Json.Serialization;
 using System.Text.Json.Serialization.Metadata;

 // Options with the reflection-based resolver (resolves any type)
 var options = new JsonSerializerOptions(JsonSerializerDefaults.Web)
 {
     TypeInfoResolver = new DefaultJsonTypeInfoResolver()
 };

 // 1) GetTypeInfo<T>() — returns a strongly-typed JsonTypeInfo<T>
 JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
 Console.WriteLine($"GetTypeInfo<Person> => Type: {personInfo.Type.Name}");

 string json = JsonSerializer.Serialize(new Person("Alice", 42), personInfo);
 Console.WriteLine($"Serialized: {json}");

 // 2) TryGetTypeInfo<T>() — probe without throwing
 if (options.TryGetTypeInfo<Person>(out var info))
 {
     Console.WriteLine($"TryGetTypeInfo<Person> succeeded: {info!.Type.Name}");
 }

 // Demonstrate TryGetTypeInfo returning false:
 // Use a source-gen context that only knows about Person.
 var restricted = new JsonSerializerOptions { TypeInfoResolver = SmallContext.Default };

 if (restricted.TryGetTypeInfo<Person>(out var personInfo2))
 {
     Console.WriteLine($"TryGetTypeInfo<Person> on restricted: found ({personInfo2!.Type.Name})");
 }
 else
 {
     Console.WriteLine("TryGetTypeInfo<Person> on restricted: NOT found");
 }

 // Order is NOT in SmallContext — TryGetTypeInfo should return false
 if (restricted.TryGetTypeInfo<Order>(out _))
 {
     Console.WriteLine("TryGetTypeInfo<Order> on restricted: found");
 }
 else
 {
     Console.WriteLine("TryGetTypeInfo<Order> on restricted: NOT found (as expected)");
 }

 // --- Types & source-gen context ----------------------------------------

 public record Person(string Name, int Age);
 public record Order(int Id, decimal Total);

 [JsonSourceGenerationOptions(WriteIndented = false)]
 [JsonSerializable(typeof(Person))]
 internal partial class SmallContext : JsonSerializerContext { }
